    try {
        const vAnswer = await $c.win.confirm('반려처리 하시겠습니까?');
        if (vAnswer === true) {
            scwin.fn_trs("37");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07321.btn_Reject_onclick' }); }
};

