 * @name grd_IsuList_onclick
 * @description grd_IsuList 클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuList_onclick = function (row, colid) {
    try {
        if (row > 0) {
            scwin.setBzProcsNo(row);
        }
        scwin.fn_sync_isuDtl();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07321.grd_IsuList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_common_info
 * @description script dts common info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_common_info = async function () {
    $c.util.getComponent("dma_scriptDtsCommonInfoReq").set("SCREN_ID", "ULDSTF07321.gfm");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO", unresolved: "query_param:SCREN_PROCES_TP_CD,BZ_PROCS_NO" };
    const sbmOptions = {
        id: "tx_script_dts_common_info",
        method: "post",
        action: "/konex/LstInvstgKonexCommon.do",
        ref: "dma_scriptDtsCommonInfoReq",
        target: "dtsCommonInfo=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_common_info_onloaderror'] === 'function') ? scwin['dts_common_info_onloaderror'] : (typeof scwin['dts_common_info_onfail'] === 'function') ? scwin['dts_common_info_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_common_info_onloadcompleted'] === 'function') ? scwin['dts_common_info_onloadcompleted'] : ((typeof scwin['dts_common_info_onsuccess'] === 'function') ? scwin['dts_common_info_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsCommonInfo'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07321.tx_script_dts_common_info" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

