/**
 * @method
 * @name setPubOfrDataSet
 * @description set Pub Ofr Data Set 처리
 * @param {*} dtsObj dtsObj
 * @param {Number} idx idx
 * @param {*} val_1 val_1
 * @param {*} val_2 val_2
 * @param {*} val_3 val_3
 * @returns {void}
 * @hidden N
 */
scwin.setPubOfrDataSet = function (dtsObj, idx, val_1, val_2, val_3) {
    (dtsObj.insertRow(), dtsObj.setRowPosition(dtsObj.getRowCount()-1));
    dtsObj.setCellData(idx, "TYPE", val_1);
    dtsObj.setCellData(idx, "SHARES", val_2);
    dtsObj.setCellData(idx, "PUBOFR_AMT", val_3);
};

/**
 * @method
 * @name setPubOfrGrid
