/**
 * @method
 * @name syncPub
 * @description sync Pub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.syncPub = async function () {
    let url = "/konex/NewListKonex.do?SCREN_ID=" + "ULDSTF07321.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=readPubOfrRslt";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;

    await scwin.tx_script_dts_PubOfr();
    const secugrpId = scwin.dts_common_info.getCellData(1, "SECUGRP");
    if (secugrpId === "주식예탁증권" || secugrpId === "외국주권") {
        ipt_med_PARVAL.MaxDecimalPlace = 3;
    } else {
        ipt_med_PARVAL.MaxDecimalPlace = 0;
    }
};

